import graphene
from graphene_file_upload.scalars import Upload
from graphql import GraphQLError
from .models import ExpenseReport, ReceiptAttachment

class BatchUploadReceiptsMutation(graphene.Mutation):
    class Arguments:
        report_id = graphene.Int(required=True)
        receipts = graphene.List(Upload, required=True)

    uploaded_count = graphene.Int()

    def mutate(self, info, report_id, receipts):
        user = info.context.user
        if not user.is_authenticated:
            raise GraphQLError("Authentication required.")

        # Restrict lookup to expense reports owned by authenticated employee
        report = ExpenseReport.objects.filter(id=report_id, employee=user).first()
        if not report:
            raise GraphQLError("Expense report not found or unauthorized.")

        created_items = []
        for receipt in receipts:
            item = ReceiptAttachment(report=report, receipt_file=receipt)
            created_items.append(item)
        ReceiptAttachment.objects.bulk_create(created_items)
        return BatchUploadReceiptsMutation(uploaded_count=len(created_items))
